package com.bank;import java.util.*;import java.util.function.*;import java.util.stream.*;public final class Reports{static void customerReport(BankingService s){Predicate<Customer>premium=c->"PREMIUM".equals(c.getCustomerType()),bangalore=c->"Bangalore".equalsIgnoreCase(c.getCity()),mangalore=c->"Mangalore".equalsIgnoreCase(c.getCity()),over105=c->c.getCustomerId()>105;Consumer<Customer>display=System.out::println;Function<Customer,String>name=Customer::getName;Supplier<Long>generator=System::currentTimeMillis;s.customers.stream().filter(premium).forEach(display);System.out.println("Bangalore: "+s.customers.stream().filter(bangalore).map(name).toList());System.out.println("Mangalore: "+s.customers.stream().filter(mangalore).map(name).toList());System.out.println("Names A: "+s.customers.stream().filter(c->c.getName().startsWith("A")).map(Customer::getName).toList());System.out.println("ID > 105: "+s.customers.stream().filter(over105).toList());System.out.println("Ascending: "+s.customers.stream().sorted(Comparator.comparing(Customer::getName)).toList());System.out.println("Descending: "+s.customers.stream().sorted(Comparator.comparing(Customer::getName).reversed()).toList());System.out.println("Type/name: "+s.customers.stream().sorted(Comparator.comparing(Customer::getCustomerType).thenComparing(Customer::getName)).toList());System.out.println("Generated account: "+generator.get());Optional<Customer>c=s.customers.stream().filter(x->x.getCustomerId()==101).findFirst();c.ifPresent(System.out::println);System.out.println(c.orElseGet(()->new Customer(0,"Guest","-","-","-","REGULAR")));}
static void accountReport(BankingService s){var a=s.accounts;System.out.println("Max: "+a.stream().max(Comparator.comparingDouble(x->x.balance)));System.out.println("Min: "+a.stream().min(Comparator.comparingDouble(x->x.balance)));System.out.println("Total: "+a.stream().map(x->x.balance).reduce(0.0,Double::sum));System.out.println("Average: "+a.stream().collect(Collectors.averagingDouble(x->x.balance)));System.out.println("Count/type: "+a.stream().collect(Collectors.groupingBy(BankAccount::type,Collectors.counting())));System.out.println("Balance/type: "+a.stream().collect(Collectors.groupingBy(BankAccount::type,Collectors.summingDouble(x->x.balance))));var totals=a.stream().collect(Collectors.groupingBy(x->x.customerId,Collectors.summingDouble(x->x.balance)));System.out.println("High-value: "+totals.entrySet().stream().filter(x->x.getValue()>100000).toList());System.out.println("Top 3: "+totals.entrySet().stream().sorted(Map.Entry.<Integer,Double>comparingByValue().reversed()).limit(3).toList());System.out.println("flatMap: "+s.customers.stream().flatMap(c->a.stream().filter(x->x.customerId==c.getCustomerId())).map(x->x.accountNumber).toList());System.out.println("skip/limit: "+a.stream().skip(2).limit(3).toList());}
static void transactionReport(BankingService s){var t=s.transactions;System.out.println("Total deposits: "+t.stream().filter(x->x.transactionType().equals("DEPOSIT")).mapToDouble(Transaction::amount).sum());System.out.println("Total withdrawals: "+t.stream().filter(x->x.transactionType().equals("WITHDRAW")).mapToDouble(Transaction::amount).sum());System.out.println("Max/min: "+t.stream().max(Comparator.comparingDouble(Transaction::amount))+" / "+t.stream().min(Comparator.comparingDouble(Transaction::amount)));System.out.println("Summary: "+t.stream().collect(Collectors.groupingBy(Transaction::transactionType,Collectors.teeing(Collectors.counting(),Collectors.averagingDouble(Transaction::amount),(c,a)->"count="+c+", average="+a))));System.out.println("Above 50000: "+t.stream().filter(x->x.amount()>50000).toList());System.out.println("Latest five: "+t.stream().sorted(Comparator.comparing(Transaction::transactionDate).reversed()).limit(5).toList());}
static void dashboard(BankingService s){double total=s.accounts.stream().map(x->x.balance).reduce(0.0,Double::sum);System.out.printf("""
%n================================%nBANKING ANALYTICS DASHBOARD%n================================%nCustomers: %d | Premium: %d%nAccounts: %d | Total: Rs. %,.2f | Average: Rs. %,.2f%nTransactions: %d%nAccounts/type: %s%nCustomers/city: %s%nPremium partition: %s%nCities: %s%n================================%n
""",s.customers.size(),s.customers.stream().filter(x->"PREMIUM".equals(x.getCustomerType())).count(),s.accounts.size(),total,s.accounts.stream().collect(Collectors.averagingDouble(x->x.balance)),s.transactions.size(),s.accounts.stream().collect(Collectors.groupingBy(BankAccount::type,Collectors.counting())),s.customers.stream().collect(Collectors.groupingBy(Customer::getCity,Collectors.counting())),s.customers.stream().collect(Collectors.partitioningBy(x->"PREMIUM".equals(x.getCustomerType()))),s.customers.stream().map(Customer::getCity).distinct().sorted().collect(Collectors.joining(", ")));}
static String classify(String t){return switch(t){case"DEPOSIT","INTEREST"->"CREDIT";case"WITHDRAW","LOAN_PAYMENT"->"DEBIT";case"TRANSFER"->"TRANSFER";default->"UNKNOWN";};}static String statement(BankAccount a,Customer c){return """
%n================================%nBANK ACCOUNT STATEMENT%n================================%nAccount Number : %d%nCustomer       : %s%nAccount Type   : %s%nBalance        : Rs. %,.2f%nStatus         : %s%n================================%nJSON:%n{"customerId":%d,"name":"%s","city":"%s"}%n
""".formatted(a.accountNumber,c.getName(),a.type(),a.balance,a.status,c.getCustomerId(),c.getName(),c.getCity());}}
